"""Resolution of platform directories the way the app computes them."""
import os


def _home_dir():
    home = os.environ.get("HOME")
    if home:
        return home
    # Fall back to the passwd database.
    try:
        import pwd
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return None


def _xdg(var, fallback_suffix):
    val = os.environ.get(var)
    if val and os.path.isabs(val):
        return val
    home = _home_dir()
    if home is None:
        return None
    return os.path.join(home, fallback_suffix)


def config_dir():
    return _xdg("XDG_CONFIG_HOME", ".config")


def cache_dir():
    return _xdg("XDG_CACHE_HOME", ".cache")


def state_dir():
    return _xdg("XDG_STATE_HOME", os.path.join(".local", "state"))


def home_dir():
    return _home_dir()


def default_config_dir():
    d = config_dir()
    return os.path.join(d, "tui-journal") if d else None


def default_log_file():
    d = cache_dir()
    return os.path.join(d, "tui-journal", "tui-journal.log") if d else None


def default_state_dir():
    d = state_dir()
    return os.path.join(d, "tui-journal") if d else None


def default_backend_dir():
    h = home_dir()
    return os.path.join(h, "tui-journal") if h else None

"""A minimal TOML parser covering the subset used by config/theme files.

Produces parse errors formatted like the Rust `toml` crate (toml_edit style),
since those messages surface to the user.
"""


class TomlError(Exception):
    def __init__(self, message, line, col, src_line):
        self.message = message
        self.line = line          # 1-based
        self.col = col            # 1-based
        self.src_line = src_line
        super().__init__(self.render())

    def render(self):
        pointer = " " * (self.col - 1) + "^"
        return (
            f"TOML parse error at line {self.line}, column {self.col}\n"
            f"  |\n"
            f"{self.line} | {self.src_line}\n"
            f"  | {pointer}\n"
            f"{self.message}\n"
        )


class _Parser:
    def __init__(self, text):
        self.text = text
        self.lines = text.split("\n")

    def parse(self):
        root = {}
        current = root
        for idx, raw in enumerate(self.lines):
            line_no = idx + 1
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("["):
                if not (line.endswith("]") and not line.startswith("[[")):
                    raise TomlError("invalid table header", line_no, 1, raw)
                path_str = line[1:-1].strip()
                parts = self._parse_key_path(path_str, line_no, raw)
                current = root
                for p in parts:
                    if p in current:
                        if not isinstance(current[p], dict):
                            raise TomlError(f"duplicate key `{p}`", line_no, 1, raw)
                    else:
                        current[p] = {}
                    current = current[p]
                continue
            # key = value
            eq = self._find_eq(raw)
            if eq is None:
                # mimic: key with no value
                col = len(raw.rstrip())
                # position after key token
                stripped = raw.lstrip()
                key_len = 0
                for ch in stripped:
                    if ch in " \t":
                        break
                    key_len += 1
                col = (len(raw) - len(stripped)) + key_len + 1
                raise TomlError("key with no value, expected `=`", line_no, col, raw)
            key_str = raw[:eq].strip()
            val_str = raw[eq + 1:].strip()
            keys = self._parse_key_path(key_str, line_no, raw)
            value = self._parse_value(val_str, line_no, raw, raw.index("=") + 1)
            target = current
            for k in keys[:-1]:
                if k not in target:
                    target[k] = {}
                target = target[k]
            target[keys[-1]] = value
        return root

    def _find_eq(self, raw):
        in_str = None
        esc = False
        for i, ch in enumerate(raw):
            if in_str:
                if in_str == '"' and esc:
                    esc = False
                elif in_str == '"' and ch == "\\":
                    esc = True
                elif ch == in_str:
                    in_str = None
            elif ch == '"' or ch == "'":
                in_str = ch
            elif ch == "#":
                return None
            elif ch == "=":
                return i
        return None

    def _parse_key_path(self, s, line_no, raw):
        parts = []
        for piece in _split_dotted(s):
            p = piece.strip()
            if p.startswith('"') and p.endswith('"') and len(p) >= 2:
                p = p[1:-1]
            elif p.startswith("'") and p.endswith("'") and len(p) >= 2:
                p = p[1:-1]
            if p == "":
                raise TomlError("invalid key", line_no, 1, raw)
            parts.append(p)
        return parts

    def _parse_value(self, s, line_no, raw, eq_col):
        # returns python value; strips trailing comment outside strings
        s_clean, _ = _strip_comment(s)
        s_clean = s_clean.strip()
        col = raw.find(s_clean, eq_col) + 1 if s_clean else eq_col + 1
        if not s_clean:
            raise TomlError("invalid value", line_no, eq_col + 2, raw)
        if s_clean.startswith('"'):
            return _parse_basic_string(s_clean, line_no, col, raw)
        if s_clean.startswith("'"):
            if not s_clean.endswith("'") or len(s_clean) < 2:
                raise TomlError("invalid string", line_no, col, raw)
            return s_clean[1:-1]
        if s_clean.startswith("{"):
            if not s_clean.endswith("}"):
                raise TomlError("invalid inline table", line_no, col, raw)
            inner = s_clean[1:-1].strip()
            tbl = {}
            if inner:
                for item in _split_commas(inner):
                    keq = item.find("=")
                    if keq < 0:
                        raise TomlError("expected `=`", line_no, col, raw)
                    k = item[:keq].strip().strip('"').strip("'")
                    v = item[keq + 1:].strip()
                    tbl[k] = self._parse_value(v, line_no, raw, raw.find(v, eq_col) - 1)
            return tbl
        if s_clean.startswith("["):
            if not s_clean.endswith("]"):
                raise TomlError("invalid array", line_no, col, raw)
            inner = s_clean[1:-1].strip()
            arr = []
            if inner:
                for item in _split_commas(inner):
                    arr.append(self._parse_value(item.strip(), line_no, raw, eq_col))
            return arr
        if s_clean == "true":
            return True
        if s_clean == "false":
            return False
        # number
        try:
            if any(c in s_clean for c in ".eE") and not s_clean.startswith("0x"):
                return float(s_clean)
            return int(s_clean.replace("_", ""), 10)
        except ValueError:
            raise TomlError(f"invalid number", line_no, col, raw)


def _split_dotted(s):
    parts = []
    cur = ""
    in_str = None
    for ch in s:
        if in_str:
            cur += ch
            if ch == in_str:
                in_str = None
        elif ch in "\"'":
            in_str = ch
            cur += ch
        elif ch == ".":
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    return parts


def _split_commas(s):
    parts = []
    cur = ""
    in_str = None
    depth = 0
    esc = False
    for ch in s:
        if in_str:
            cur += ch
            if in_str == '"' and ch == "\\" and not esc:
                esc = True
                continue
            if ch == in_str and not esc:
                in_str = None
            esc = False
        elif ch in "\"'":
            in_str = ch
            cur += ch
        elif ch in "[{":
            depth += 1
            cur += ch
        elif ch in "]}":
            depth -= 1
            cur += ch
        elif ch == "," and depth == 0:
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    if cur.strip():
        parts.append(cur)
    return parts


def _strip_comment(s):
    in_str = None
    esc = False
    for i, ch in enumerate(s):
        if in_str:
            if in_str == '"' and ch == "\\" and not esc:
                esc = True
                continue
            if ch == in_str and not esc:
                in_str = None
            esc = False
        elif ch in "\"'":
            in_str = ch
        elif ch == "#":
            return s[:i], s[i:]
    return s, ""


def _parse_basic_string(s, line_no, col, raw):
    if len(s) < 2 or not s.endswith('"'):
        raise TomlError("invalid string", line_no, col, raw)
    body = s[1:-1]
    out = []
    i = 0
    while i < len(body):
        ch = body[i]
        if ch == "\\" and i + 1 < len(body):
            nxt = body[i + 1]
            mapping = {"n": "\n", "t": "\t", "r": "\r", "\\": "\\", '"': '"', "'": "'"}
            if nxt in mapping:
                out.append(mapping[nxt])
                i += 2
                continue
            if nxt == "u" and i + 5 < len(body) + 1:
                try:
                    out.append(chr(int(body[i + 2:i + 6], 16)))
                    i += 6
                    continue
                except (ValueError, OverflowError):
                    pass
            raise TomlError("invalid escape sequence", line_no, col + i + 1, raw)
        out.append(ch)
        i += 1
    return "".join(out)


def loads(text):
    return _Parser(text).parse()

"""Application settings: defaults, config file loading, CLI overrides."""
import os

import paths
import tomlmini


class SettingsError(Exception):
    pass


def _default(name, fallback=None):
    raise NotImplementedError


class Settings:
    def __init__(self):
        self.backend_type = "Sqlite"
        self.scroll_per_page = 5
        self.sync_os_clipboard = False
        self.history_limit = 10
        self.colored_tags = True
        self.datum_visibility = "show"
        sd = paths.default_state_dir()
        self.app_state_dir = sd if sd else ""
        self.export_show_confirmation = True
        self.external_editor_auto_save = False
        self.external_editor_temp_file_extension = "txt"
        bd = paths.default_backend_dir()
        self.json_file_path = os.path.join(bd, "entries.json") if bd else ""
        self.sqlite_file_path = os.path.join(bd, "entries.db") if bd else ""

    # -------------------------------------------------------------
    def to_toml(self):
        def q(s):
            return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'

        def b(v):
            return "true" if v else "false"

        lines = [
            f"backend_type = {q(self.backend_type)}",
            f"scroll_per_page = {self.scroll_per_page}",
            f"sync_os_clipboard = {b(self.sync_os_clipboard)}",
            f"history_limit = {self.history_limit}",
            f"colored_tags = {b(self.colored_tags)}",
            f"datum_visibility = {q(self.datum_visibility)}",
            f"app_state_dir = {q(self.app_state_dir)}",
            "",
            "[export]",
            f"show_confirmation = {b(self.export_show_confirmation)}",
            "",
            "[external_editor]",
            f"auto_save = {b(self.external_editor_auto_save)}",
            f"temp_file_extension = {q(self.external_editor_temp_file_extension)}",
            "",
            "[json_backend]",
            f"file_path = {q(self.json_file_path)}",
            "",
            "[sqlite_backend]",
            f"file_path = {q(self.sqlite_file_path)}",
            "",
        ]
        return "\n".join(lines)


def _type_name(v):
    if isinstance(v, bool):
        return f"boolean `{str(v).lower()}`"
    if isinstance(v, str):
        return f"string \"{v}\""
    if isinstance(v, int):
        return f"integer `{v}`"
    if isinstance(v, float):
        return f"float `{v}`"
    if isinstance(v, list):
        return "array"
    if isinstance(v, dict):
        return "map"
    return type(v).__name__


def load(cli):
    """Build final Settings from defaults + config file + CLI overrides."""
    st = Settings()

    # resolve config directory
    if cli.config is not None:
        cfg_path = cli.config
        if os.path.isfile(cfg_path):
            # backward compatibility: direct path to the config file
            config_dir = os.path.dirname(cfg_path) or "."
            config_file = cfg_path
        elif os.path.isdir(cfg_path):
            config_dir = cfg_path
            config_file = os.path.join(cfg_path, "config.toml")
        else:
            raise SettingsError(
                f"Provided custom directory doesn't exit. Path: {cfg_path}")
    else:
        config_dir = paths.default_config_dir()
        config_file = os.path.join(config_dir, "config.toml") if config_dir else None

    if config_file and os.path.isfile(config_file):
        try:
            with open(config_file, "r", encoding="utf-8") as f:
                text = f.read()
        except OSError as e:
            raise SettingsError(f"Failed to read configuration file. Error infos: {e}")
        try:
            data = tomlmini.loads(text)
        except tomlmini.TomlError as e:
            raise SettingsError(f"Failed to read configuration file. Error infos: {e.render()}")
        _apply_config(st, data)

    # CLI overrides: -j first, then -s, then -b (fixed order)
    if cli.json_file_path is not None:
        st.json_file_path = cli.json_file_path
        st.backend_type = "Json"
    if cli.sqlite_file_path is not None:
        st.sqlite_file_path = cli.sqlite_file_path
        st.backend_type = "Sqlite"
    if cli.backend_type is not None:
        st.backend_type = "Json" if cli.backend_type == "json" else "Sqlite"

    return st, config_dir


def _wrong_type(key, value, expected, line_info=None):
    raise SettingsError(
        f"Failed to read configuration file. Error infos: invalid type: {_type_name(value)}, expected {expected}")


def _apply_config(st, data):
    for key, value in data.items():
        if key == "backend_type":
            if not isinstance(value, str):
                _wrong_type(key, value, "a string")
            if value not in ("Json", "Sqlite"):
                raise SettingsError(
                    "Failed to read configuration file. Error infos: unknown variant "
                    f"`{value}`, expected `Json` or `Sqlite`")
            st.backend_type = value
        elif key == "scroll_per_page":
            if not isinstance(value, int) or isinstance(value, bool):
                _wrong_type(key, value, "u16")
            st.scroll_per_page = value
        elif key == "sync_os_clipboard":
            if not isinstance(value, bool):
                _wrong_type(key, value, "a boolean")
            st.sync_os_clipboard = value
        elif key == "history_limit":
            if not isinstance(value, int) or isinstance(value, bool):
                _wrong_type(key, value, "u32")
            st.history_limit = value
        elif key == "colored_tags":
            if not isinstance(value, bool):
                _wrong_type(key, value, "a boolean")
            st.colored_tags = value
        elif key == "datum_visibility":
            if not isinstance(value, str):
                _wrong_type(key, value, "a string")
            st.datum_visibility = value
        elif key == "app_state_dir":
            if not isinstance(value, str):
                _wrong_type(key, value, "a string")
            st.app_state_dir = value
        elif key == "export":
            if isinstance(value, dict):
                for k2, v2 in value.items():
                    if k2 == "show_confirmation":
                        if not isinstance(v2, bool):
                            _wrong_type(k2, v2, "a boolean")
                        st.export_show_confirmation = v2
        elif key == "external_editor":
            if isinstance(value, dict):
                for k2, v2 in value.items():
                    if k2 == "auto_save":
                        if not isinstance(v2, bool):
                            _wrong_type(k2, v2, "a boolean")
                        st.external_editor_auto_save = v2
                    elif k2 == "temp_file_extension":
                        if not isinstance(v2, str):
                            _wrong_type(k2, v2, "a string")
                        st.external_editor_temp_file_extension = v2
        elif key == "json_backend":
            if isinstance(value, dict):
                for k2, v2 in value.items():
                    if k2 == "file_path":
                        if not isinstance(v2, str):
                            _wrong_type(k2, v2, "a string")
                        st.json_file_path = v2
        elif key == "sqlite_backend":
            if isinstance(value, dict):
                for k2, v2 in value.items():
                    if k2 == "file_path":
                        if not isinstance(v2, str):
                            _wrong_type(k2, v2, "a string")
                        st.sqlite_file_path = v2
        # unknown keys are ignored

import os
import sys

import cli as cli_mod
import settings as settings_mod
import themes_default


def _eprint(text):
    sys.stderr.write(text)


def main():
    try:
        cli = cli_mod.parse(sys.argv[1:])
    except cli_mod.CliExit as e:
        if e.stderr:
            _eprint(e.text)
        else:
            sys.stdout.write(e.text)
        return e.code

    try:
        st, config_dir = settings_mod.load(cli)
    except settings_mod.SettingsError as e:
        _eprint(f"Error: {e}\n")
        return 1

    cmd = cli.command

    if cmd == "print-config":
        sys.stdout.write(st.to_toml() + "\n")
        return 0

    if cmd and cmd.startswith("theme "):
        sub = cmd.split(" ", 1)[1]
        themes_path = os.path.join(config_dir, "themes.toml") if config_dir else "themes.toml"
        if sub == "print-path":
            sys.stdout.write(themes_path + "\n")
            return 0
        if sub == "print-default":
            sys.stdout.write(themes_default.DEFAULT_THEMES + "\n")
            return 0
        if sub == "write-defaults":
            if os.path.exists(themes_path):
                _eprint(f"Error: Themes file already exists. Path: {themes_path}\n")
                return 1
            parent = os.path.dirname(themes_path)
            if parent:
                os.makedirs(parent, exist_ok=True)
            try:
                with open(themes_path, "w", encoding="utf-8") as f:
                    f.write(themes_default.DEFAULT_THEMES)
            except OSError as e:
                _eprint(f"Error: {e}\n")
                return 1
            sys.stdout.write(f"Default themes have been written to {themes_path}\n")
            return 0

    # Remaining commands launch the terminal UI.
    import tui_app
    return tui_app.run(cli, st, config_dir)


if __name__ == "__main__":
    sys.exit(main())

