"""Low-level terminal handling: raw mode, alternate screen, input parsing."""
import os
import re
import sys
import termios
import tty
import signal


class KeyEvent:
    __slots__ = ("kind", "char", "code", "ctrl", "alt", "shift")

    # kind: 'char', 'code'  (code in: up/down/left/right/home/end/delete/backspace/
    #        enter/tab/backtab/esc/pageup/pagedown/insert/f1..f12)
    def __init__(self, kind, char=None, code=None, ctrl=False, alt=False, shift=False):
        self.kind = kind
        self.char = char
        self.code = code
        self.ctrl = ctrl
        self.alt = alt
        self.shift = shift

    def __repr__(self):
        return f"KeyEvent({self.kind},{self.char!r},{self.code!r},c={self.ctrl},a={self.alt},s={self.shift})"


class Terminal:
    def __init__(self):
        self.tty_fd = None
        self.out = None
        self.old_attrs = None
        self.width = 80
        self.height = 24

    def open(self):
        """Raises OSError(6) when there is no controlling terminal."""
        try:
            fd = os.open("/dev/tty", os.O_RDWR)
        except OSError:
            fd = None
        if fd is None:
            raise OSError(6, "No such device or address")
        self.tty_fd = fd
        self.out = os.dup(fd)
        self.old_attrs = termios.tcgetattr(fd)
        tty.setraw(fd)
        self.update_size()
        signal.signal(signal.SIGWINCH, lambda *_: self.update_size())

    def write(self, data):
        os.write(self.out, data.encode("utf-8", "replace"))

    def flush(self):
        pass

    def update_size(self):
        try:
            sz = os.get_terminal_size(self.tty_fd)
            self.width, self.height = sz.columns, sz.lines
        except OSError:
            pass

    def enter_ui(self):
        self.write("\x1b[?1049h\x1b[?25l")

    def leave_ui(self):
        self.write("\x1b[?25h\x1b[?1049l")

    def close(self):
        if self.tty_fd is not None:
            try:
                self.leave_ui()
                termios.tcsetattr(self.tty_fd, termios.TCSADRAIN, self.old_attrs)
            except OSError:
                pass
            os.close(self.tty_fd)
            os.close(self.out)
            self.tty_fd = None

    # ------------------------------------------------------------ input ----
    def read_key(self):
        """Blocking read of one key event."""
        data = self._read_some()
        return self._parse(data)

    def _read_some(self):
        # read at least one byte, then gather any immediately-available bytes
        first = os.read(self.tty_fd, 1)
        if not first:
            return b""
        if first != b"\x1b":
            return first
        # possibly an escape sequence; gather with small timeout
        import select
        buf = first
        while True:
            r, _, _ = select.select([self.tty_fd], [], [], 0.02)
            if not r:
                break
            chunk = os.read(self.tty_fd, 64)
            if not chunk:
                break
            buf += chunk
            if len(buf) > 64:
                break
            # stop if the sequence looks complete
            if _SEQ_COMPLETE.match(buf):
                break
        return buf

    def _parse(self, data):
        if not data:
            return None
        b0 = data[0]
        if b0 == 0x1B:
            return _parse_escape(data)
        if b0 == 0x0D:
            return KeyEvent("code", code="enter")
        if b0 == 0x09:
            return KeyEvent("code", code="tab")
        if b0 == 0x7F:
            return KeyEvent("code", code="backspace")
        if b0 == 0x08:
            return KeyEvent("code", code="backspace", ctrl=True)
        if b0 < 0x20:
            ch = chr(b0 + 0x60)
            return KeyEvent("char", char=ch, ctrl=True)
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError:
            return None
        return KeyEvent("char", char=text)


_SEQ_COMPLETE = re.compile(rb"^\x1b(\[[0-9;?]*[A-Za-z~]|\[M.{0,3}|O[A-Za-z]|.|$)", re.S)

_CSI_KEYS = {
    "A": "up", "B": "down", "C": "right", "D": "left",
    "H": "home", "F": "end", "Z": "backtab",
    "1~": "home", "2~": "insert", "3~": "delete", "4~": "end",
    "5~": "pageup", "6~": "pagedown", "7~": "home", "8~": "end",
}


def _parse_escape(data):
    if len(data) == 1:
        return KeyEvent("code", code="esc")
    rest = data[1:]
    if rest.startswith(b"[") or rest.startswith(b"O"):
        body = rest[1:]
        try:
            s = body.decode("ascii", "replace")
        except Exception:
            return None
        if s in _CSI_KEYS:
            return KeyEvent("code", code=_CSI_KEYS[s])
        m = re.match(r"^([0-9]*)(?:;([0-9]+))?([ABCDHFZ~])$", s)
        if m:
            num, mod, final = m.groups()
            key = None
            if final == "~":
                key = _CSI_KEYS.get(num + "~")
            else:
                key = _CSI_KEYS.get(final)
            if key is None and final in "HF":
                key = "home" if final == "H" else "end"
            if key:
                ctrl = alt = shift = False
                if mod:
                    mv = int(mod) - 1
                    shift = bool(mv & 1)
                    alt = bool(mv & 2)
                    ctrl = bool(mv & 4)
                if key == "backtab":
                    shift = True
                return KeyEvent("code", code=key, ctrl=ctrl, alt=alt, shift=shift)
        return None
    # Alt + key
    inner = _parse(rest) if rest else None
    if inner is not None:
        inner.alt = True
        if inner.code == "esc":
            inner.code = None
        return inner
    return None

"""Screen buffer, styles, and widget rendering helpers (mini-ratatui)."""
import unicodedata

NAMED_COLORS = {
    "Black": 0, "Red": 1, "Green": 2, "Yellow": 3, "Blue": 4,
    "Magenta": 5, "Cyan": 6, "Gray": 7, "DarkGray": 8, "LightRed": 9,
    "LightGreen": 10, "LightYellow": 11, "LightBlue": 12,
    "LightMagenta": 13, "LightCyan": 14, "White": 15,
}

MOD_BITS = {
    "BOLD": 1, "DIM": 2, "ITALIC": 4, "UNDERLINED": 8, "SLOW_BLINK": 16,
    "RAPID_BLINK": 32, "REVERSED": 64, "HIDDEN": 128, "CROSSED_OUT": 256,
}
MOD_SGR = {
    "BOLD": 1, "DIM": 2, "ITALIC": 3, "UNDERLINED": 4, "SLOW_BLINK": 5,
    "RAPID_BLINK": 6, "REVERSED": 7, "HIDDEN": 8, "CROSSED_OUT": 9,
}


def wcwidth(ch):
    if not ch:
        return 0
    o = ord(ch)
    if o == 0:
        return 0
    if o < 32 or 0x7F <= o < 0xA0:
        return 0
    if unicodedata.combining(ch):
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    return 1


def str_width(s):
    return sum(wcwidth(c) for c in s)


class Color:
    __slots__ = ("kind", "value")

    def __init__(self, kind, value=None):
        self.kind = kind      # 'reset' | 'named' | 'rgb'
        self.value = value

    def sgr_fg(self):
        if self.kind == "reset":
            return "39"
        if self.kind == "named":
            return f"38;5;{self.value}"
        r, g, b = self.value
        return f"38;2;{r};{g};{b}"

    def sgr_bg(self):
        if self.kind == "reset":
            return "49"
        if self.kind == "named":
            return f"48;5;{self.value}"
        r, g, b = self.value
        return f"48;2;{r};{g};{b}"

    def __eq__(self, other):
        return isinstance(other, Color) and (self.kind, self.value) == (other.kind, other.value)

    def __hash__(self):
        return hash((self.kind, self.value))


RESET_COLOR = Color("reset")


def parse_color(text):
    text = text.strip()
    if text == "Reset":
        return Color("reset")
    if text in NAMED_COLORS:
        return Color("named", NAMED_COLORS[text])
    if text.startswith("#") and len(text) == 7:
        try:
            r = int(text[1:3], 16)
            g = int(text[3:5], 16)
            b = int(text[5:7], 16)
            return Color("rgb", (r, g, b))
        except ValueError:
            pass
    raise ValueError(f"invalid color: {text}")


class Style:
    __slots__ = ("fg", "bg", "mods", "underline")

    def __init__(self, fg=None, bg=None, mods=0, underline=None):
        self.fg = fg            # Color or None
        self.bg = bg
        self.mods = mods        # bitmask of MOD_BITS
        self.underline = underline

    def copy(self):
        return Style(self.fg, self.bg, self.mods, self.underline)

    def sgr(self):
        parts = []
        if self.mods:
            for name, bit in MOD_BITS.items():
                if self.mods & bit:
                    parts.append(str(MOD_SGR[name]))
        if self.fg is not None:
            parts.append(self.fg.sgr_fg())
        if self.bg is not None:
            parts.append(self.bg.sgr_bg())
        if self.underline is not None and (self.mods & MOD_BITS["UNDERLINED"]):
            parts.append("58;" + self.underline.sgr_fg().split(";", 1)[1])
        return "\x1b[" + ";".join(parts) + "m" if parts else ""

    def key(self):
        return (self.fg, self.bg, self.mods, self.underline)

    def __eq__(self, other):
        return isinstance(other, Style) and self.key() == other.key()

    def __hash__(self):
        return hash(self.key())


DEFAULT_STYLE = Style()


class Cell:
    __slots__ = ("ch", "style", "width")

    def __init__(self, ch=" ", style=None, width=1):
        self.ch = ch
        self.style = style if style is not None else DEFAULT_STYLE
        self.width = width


class Rect:
    __slots__ = ("x", "y", "w", "h")

    def __init__(self, x, y, w, h):
        self.x = x
        self.y = y
        self.w = w
        self.h = h

    @property
    def right(self):
        return self.x + self.w

    @property
    def bottom(self):
        return self.y + self.h

    def inner(self, margin=1):
        if self.w < 2 * margin or self.h < 2 * margin:
            return Rect(self.x, self.y, 0, 0)
        return Rect(self.x + margin, self.y + margin, self.w - 2 * margin, self.h - 2 * margin)


class Buffer:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.cells = [[Cell() for _ in range(width)] for _ in range(height)]

    def clear_area(self, rect, style=None):
        for y in range(rect.y, min(rect.bottom, self.height)):
            row = self.cells[y]
            for x in range(rect.x, min(rect.right, self.width)):
                row[x] = Cell(" ", style)

    def set(self, x, y, ch, style=None):
        if 0 <= x < self.width and 0 <= y < self.height:
            w = wcwidth(ch)
            self.cells[y][x] = Cell(ch, style, max(w, 1) if w == 0 else w)
            if w == 2 and x + 1 < self.width:
                self.cells[y][x + 1] = Cell("", style, 0)

    def write_str(self, x, y, text, style=None, max_x=None):
        cx = x
        limit = max_x if max_x is not None else self.width
        for ch in text:
            w = wcwidth(ch)
            if w == 0:
                continue
            if cx + w > limit:
                break
            self.set(cx, y, ch, style)
            cx += w
        return cx

    def render_to(self, term, cursor=None):
        out = ["\x1b[1;1H"]
        cur_style = None
        for y in range(self.height):
            row = self.cells[y]
            if y > 0:
                out.append(f"\x1b[{y + 1};1H")
                cur_style = None
            for cell in row:
                if cell.width == 0:
                    continue
                if cell.style != cur_style:
                    out.append("\x1b[0m")
                    sgr = cell.style.sgr()
                    if sgr:
                        out.append(sgr)
                    cur_style = cell.style
                out.append(cell.ch)
        out.append("\x1b[0m")
        if cursor is not None:
            cx, cy = cursor
            out.append(f"\x1b[{cy + 1};{cx + 1}H\x1b[?25h")
        else:
            out.append("\x1b[?25l")
        term.write("".join(out))


BORDER_CHARS = {
    "tl": "┌", "tr": "┐", "bl": "└", "br": "┘", "h": "─", "v": "│",
}


def render_block(buf, rect, title=None, border_style=None, title_style=None,
                 bottom_right=None, base_style=None):
    """Draw a bordered block. Title at top-left, optional text at bottom-right."""
    if rect.w < 2 or rect.h < 2:
        return Rect(rect.x, rect.y, 0, 0)
    bs = border_style
    B = BORDER_CHARS
    # corners and edges
    buf.set(rect.x, rect.y, B["tl"], bs)
    buf.set(rect.right - 1, rect.y, B["tr"], bs)
    buf.set(rect.x, rect.bottom - 1, B["bl"], bs)
    buf.set(rect.right - 1, rect.bottom - 1, B["br"], bs)
    for x in range(rect.x + 1, rect.right - 1):
        buf.set(x, rect.y, B["h"], bs)
        buf.set(x, rect.bottom - 1, B["h"], bs)
    for y in range(rect.y + 1, rect.bottom - 1):
        buf.set(rect.x, y, B["v"], bs)
        buf.set(rect.right - 1, y, B["v"], bs)
    # interior
    inner = rect.inner(1)
    buf.clear_area(inner, base_style)
    if title:
        buf.write_str(rect.x + 1, rect.y, title,
                      title_style if title_style is not None else bs,
                      max_x=rect.right - 1)
    if bottom_right:
        tw = str_width(bottom_right)
        buf.write_str(rect.right - 1 - tw, rect.bottom - 1, bottom_right,
                      title_style if title_style is not None else bs,
                      max_x=rect.right - 1)
    return inner


def centered_rect(buf, percent_x, percent_y):
    """ratatui's customary centered_rect helper."""
    pw = buf.width * percent_x // 100
    ph = buf.height * percent_y // 100
    x = (buf.width - pw) // 2
    y = (buf.height - ph) // 2
    return Rect(x, y, pw, ph)

"""Journal entry model and shared helpers."""
import datetime


class Entry:
    __slots__ = ("id", "date", "title", "content", "tags", "priority")

    def __init__(self, id=0, date=None, title="", content="", tags=None, priority=None):
        self.id = id
        self.date = date or datetime.date.today()
        self.title = title
        self.content = content
        self.tags = list(tags) if tags else []
        self.priority = priority

    def to_transfer(self):
        return {
            "id": self.id,
            "date": format_date_rfc3339_z(self.date),
            "title": self.title,
            "content": self.content,
            "tags": list(self.tags),
            "priority": self.priority,
        }


def format_date_rfc3339_z(d):
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}T00:00:00Z"


def format_date_rfc3339_offset(d):
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}T00:00:00+00:00"


def parse_date_rfc3339(s):
    """Parse dates like 2026-08-09T00:00:00Z or 2026-08-09T00:00:00+00:00."""
    s = s.strip()
    try:
        if s.endswith("Z"):
            dt = datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ")
            return dt.date()
        if "+" in s[10:] or s[10:].count("-") > 0 and "T" in s:
            # offset form
            main = s
            dt = datetime.datetime.fromisoformat(main)
            return dt.date()
        if "T" in s:
            return datetime.datetime.strptime(s, "%Y-%m-%dT%H:%M:%S").date()
        return datetime.datetime.strptime(s, "%Y-%m-%d").date()
    except ValueError:
        return None


def parse_display_date(s):
    """Parse user-entered date in DD-MM-YYYY."""
    s = s.strip()
    try:
        return datetime.datetime.strptime(s, "%d-%m-%Y").date()
    except ValueError:
        return None

